// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }

    function testFuzz_property(uint256 _val) public {

        bool ok1;
        try c.SetMinSum(_val) { ok1 = true; } catch { ok1 = false; }
        assertTrue(ok1, "first SetMinSum must succeed on reference");

        c.Initialized();

        bool ok2;
        try c.SetMinSum(_val) { ok2 = true; } catch { ok2 = false; }

        assertTrue(!ok2, "after Initialized, SetMinSum must revert on reference");
    }
}
